const body = $json.body;
const platforms = body.platforms || ['youtube'];

return platforms.map(function(platform) {
  return {
    json: {
      platform: platform.toLowerCase(),
      youtubeApiKey: body.youtubeApiKey || '',
      youtubeChannelId: body.youtubeChannelId || 'UCEbgisMMr3fbM-YV_agJRdA',
      facebookToken: body.facebookToken || '',
      facebookPageId: body.facebookPageId || ''
    }
  };
});

const items = $json.items || [];
const videos = items.slice(0, 5);

if (!videos.length) {
  return [{ json: { platform: 'YouTube', title: 'Aucune video trouvee', description: '', content_text: '', postUrl: '', views: null, likes: null, comments: null } }];
}

return videos.map(function(video) {
  const snippet = video.snippet || {};
  const videoId = video.id && video.id.videoId ? video.id.videoId : '';
  return {
    json: {
      platform: 'YouTube',
      title: snippet.title || '',
      description: snippet.description || '',
      content_text: snippet.description || '',
      postUrl: 'https://youtube.com/watch?v=' + videoId,
      publishedAt: snippet.publishedAt ? snippet.publishedAt.split('T')[0] : '',
      views: null,
      likes: null,
      comments: null
    }
  };
});

const response = $json;
let posts = [];

if (Array.isArray(response)) {
  posts = response;
} else if (response.items) {
  posts = response.items;
}

posts = posts.slice(0, 5);

if (!posts.length) {
  return [{
    json: {
      platform: 'Instagram',
      title: 'Instagram - Aucun post dans le dataset Apify',
      description: '',
      content_text: 'Relancer l acteur Apify Instagram pour rafraichir les donnees.',
      postUrl: '',
      views: null, likes: null, comments: null
    }
  }];
}

return posts.map(function(post) {
  const date = post.timestamp
    ? post.timestamp.split('T')[0]
    : new Date().toISOString().split('T')[0];

  const caption = post.caption || post.text || '';
  const title = caption.substring(0, 80) || ('Post Instagram - ' + date);

  return {
    json: {
      platform: 'Instagram',
      title: title,
      description: caption,
      content_text: caption,
      postUrl: post.url || post.postUrl || ('https://instagram.com/p/' + (post.shortCode || '')),
      views: post.videoViewCount || post.videoPlayCount || null,
      likes: post.likesCount || null,
      comments: post.commentsCount || null
    }
  };
});

// Apify retourne un tableau direct ou { items: [...] }
let response = $json;
let videos = [];

if (Array.isArray(response)) {
  videos = response;
} else if (response.items && Array.isArray(response.items)) {
  videos = response.items;
} else if (response.data && Array.isArray(response.data)) {
  videos = response.data;
}

videos = videos.slice(0, 5);

if (!videos.length) {
  return [{
    json: {
      platform: 'TikTok',
      title: 'TikTok - Dataset Apify vide',
      description: '',
      content_text: 'Relancer l acteur Apify pour rafraichir les donnees TikTok.',
      postUrl: '',
      views: null,
      likes: null,
      comments: null
    }
  }];
}

return videos.map(function(video) {
  // Gerer les differents formats Apify TikTok
  const text = video.text || video.desc || video.title || video.description || '';
  const createTime = video.createTimeISO
    ? video.createTimeISO.split('T')[0]
    : (video.createTime ? new Date(video.createTime * 1000).toISOString().split('T')[0] : '');
  const videoUrl = video.webVideoUrl || video.videoUrl || video.url || '';
  const plays = video.playCount || (video.stats && video.stats.playCount) || video.diggCount || null;
  const likes = video.diggCount || (video.stats && video.stats.diggCount) || null;
  const comments = video.commentCount || (video.stats && video.stats.commentCount) || null;

  return {
    json: {
      platform: 'TikTok',
      title: (text || 'Video TikTok').substring(0, 120),
      description: text,
      content_text: text,
      postUrl: videoUrl,
      publishedAt: createTime,
      views: plays,
      likes: likes,
      comments: comments
    }
  };
});

const input = $json;
const token = input.facebookToken || '';
if (!token) {
  return [{
    json: {
      platform: 'Facebook',
      title: 'Facebook - Token non configure',
      description: '',
      content_text: 'Le token Meta Graph API (facebookToken) n est pas configure. Configurer le token dans les parametres de l application.',
      postUrl: '',
      views: null,
      likes: null,
      comments: null
    }
  }];
}
const posts = input.data || [];
if (!posts.length) {
  return [{ json: { platform: 'Facebook', title: 'Aucun post trouve', description: '', content_text: '', postUrl: '', views: null, likes: null, comments: null } }];
}
return posts.slice(0, 5).map(function(post) {
  const date = post.created_time ? post.created_time.split('T')[0] : '';
  return {
    json: {
      platform: 'Facebook',
      title: 'Post Facebook - ' + date,
      description: post.message || '',
      content_text: post.message || '',
      postUrl: 'https://facebook.com/' + (post.id || ''),
      views: null,
      likes: post.reactions ? post.reactions.summary.total_count : null,
      comments: post.comments ? post.comments.summary.total_count : null
    }
  };
});

const body = $json;
const platform = body.platform || 'Non specifie';
const title = body.title || '';
const description = body.description || '';
const content = body.content_text || '';
const postUrl = body.postUrl || '';
const views = body.views !== undefined && body.views !== null ? body.views : null;
const likes = body.likes !== undefined && body.likes !== null ? body.likes : null;
const comments = body.comments !== undefined && body.comments !== null ? body.comments : null;

let kpiSection = '';
if (views !== null || likes !== null || comments !== null) {
  kpiSection = 'KPI MESURES (a integrer dans l analyse engagement) :\n' +
    (views !== null ? '- Vues / Lectures : ' + views + '\n' : '') +
    (likes !== null ? '- Likes / J aime : ' + likes + '\n' : '') +
    (comments !== null ? '- Commentaires : ' + comments + '\n' : '') +
    '\n';
}

const prompt = 'Tu es un expert en marketing de contenu specialise dans les psychologues et coachs bien-etre francophones.\n\n' +
  'Analyse ce contenu publie par Anna Ollivier, psychologue clinicienne qui developpe une formation en ligne sur la gestion emotionnelle.\n\n' +
  '---\n' +
  'PLATEFORME: ' + platform + '\n' +
  'TITRE: ' + title + '\n' +
  'DESCRIPTION: ' + description + '\n' +
  'CONTENU / TRANSCRIPTION:\n' + content + '\n' +
  (kpiSection ? kpiSection : '') +
  '---\n\n' +
  'Evalue selon 6 axes (score 1 a 10) :\n' +
  '1. HOOK - Accroche, curiosite, identification emotionnelle dans les 3 premieres secondes ou phrases\n' +
  '2. CLARTE - Positionnement unique visible, promesse claire, difference vs concurrents\n' +
  '3. CTA - Appel a action present, clair, adapte a la plateforme\n' +
  '4. SEO - Mots-cles psychologie, emotions, anxiete, bien-etre, confiance en soi\n' +
  '5. ENGAGEMENT - Empathie, storytelling, validation de la douleur du persona' + (views !== null ? ' (tenir compte des KPI reels)' : '') + '\n' +
  '6. ALIGNEMENT - Pertinence pour adultes 25-45 ans cherchant des outils pratiques pour leurs emotions\n\n' +
  'Score global = moyenne ponderee (hook x1.5, engagement x1.5, autres x1) divisee par 6.5 fois 10.\n\n' +
  'Pour mots_cles : liste 8 a 12 mots-cles SEO longue traine pertinents (sans #, en minuscules).\n' +
  'Pour hashtags : liste 5 hashtags avec # optimises pour la plateforme indiquee.\n\n' +
  'Reponds UNIQUEMENT avec un JSON valide, sans backtick ni commentaire :\n' +
  '{"scores":{"hook":0,"clarte":0,"cta":0,"seo":0,"engagement":0,"alignement":0,"global":0},"points_forts":["p1","p2","p3"],"axes_amelioration":["a1","a2","a3"],"hook_suggere":"...","mots_cles":["mc1","mc2","mc3","mc4","mc5","mc6","mc7","mc8"],"hashtags":["#h1","#h2","#h3","#h4","#h5"],"resume_analyse":"Synthese en 3 phrases"}';

const apiBody = JSON.stringify({
  model: 'claude-sonnet-4-20250514',
  max_tokens: 2000,
  messages: [{ role: 'user', content: prompt }]
});

return [{ json: { prompt, platform, title, description, content, postUrl, views, likes, comments, apiBody } }];

const claudeResponse = $json;
let claudeText = '';
if (claudeResponse.content && Array.isArray(claudeResponse.content)) {
  claudeText = claudeResponse.content[0].text || '';
} else {
  claudeText = JSON.stringify(claudeResponse);
}

let analysis = {};
try {
  analysis = JSON.parse(claudeText);
} catch(e) {
  const start = claudeText.indexOf('{');
  const end = claudeText.lastIndexOf('}');
  if (start !== -1 && end !== -1) {
    try { analysis = JSON.parse(claudeText.substring(start, end + 1)); } catch(e2) {}
  }
}

// Utiliser .item pour correspondre a l item courant (et non toujours le premier)
const prev = $('Build Prompt').item.json;
const scores = analysis.scores || {};

return [{
  json: {
    platform: prev.platform,
    title: prev.title,
    postUrl: prev.postUrl,
    views: prev.views,
    likes: prev.likes,
    comments: prev.comments,
    scoreHook: scores.hook || 0,
    scoreClarte: scores.clarte || 0,
    scoreCta: scores.cta || 0,
    scoreSeo: scores.seo || 0,
    scoreEngagement: scores.engagement || 0,
    scoreAlignement: scores.alignement || 0,
    scoreGlobal: scores.global || 0,
    pointsForts: (analysis.points_forts || []).join('\n'),
    axesAmelioration: (analysis.axes_amelioration || []).join('\n'),
    hookSuggere: analysis.hook_suggere || '',
    hashtags: (analysis.hashtags || []).join(' '),
    resumeAnalyse: analysis.resume_analyse || '',
    motsCles: (analysis.mots_cles || []).join(', '),
    dateAnalyse: new Date().toISOString().split('T')[0]
  }
}];

// Appel LLM — Ollama du VPS, reseau Docker interne.
// AUCUNE authentification, donc AUCUN secret dans ce noeud. C'est la raison du
// basculement depuis Anthropic, dont la cle etait ecrite en dur ici : un noeud
// Code N8N ne peut ni lire $env ni utiliser httpRequestWithAuthentication, donc
// appeler une API a cle depuis un Code node oblige a versionner le secret.
const OLLAMA_URL = 'http://172.18.0.1:11434/api/chat';
const MODELE = 'glm-5.2:cloud';
const NUM_PREDICT = 2000;

const prompt = $input.first().json.prompt;

let responseText = null;
let erreur = null;

try {
  const resp = await this.helpers.httpRequest({
    method: 'POST',
    url: OLLAMA_URL,
    body: JSON.stringify({
      model: MODELE,
      messages: [{ role: 'user', content: prompt }],
      stream: false,
      // Obligatoire : sur un modele de raisonnement, le « thinking » consomme
      // tout num_predict et message.content revient vide.
      think: false,
      options: { num_predict: NUM_PREDICT }
    }),
    timeout: 300000
  });
  if (resp && resp.message && resp.message.content) {
    responseText = resp.message.content;
  } else {
    erreur = 'reponse sans message.content (think non desactive ?)';
  }
} catch (e) {
  erreur = e.message;
}

if (!responseText) {
  throw new Error('Appel LLM (' + MODELE + ') echoue : ' + (erreur || 'inconnue'));
}

// Sortie au format Anthropic : les noeuds Parse en aval restent inchanges.
return [{ json: {
  content: [{ type: 'text', text: responseText }],
  model: MODELE,
  type: 'message',
  role: 'assistant'
} }];
